                    const yReg = (opcode >> 4) & 0x0F;
                    this.v[xReg] = this.v[yReg];
                } else {
                    instr = `Unknown F${this.toHex(opcode & 0x0FFF)}`;
                }
            }

        }

        return instr;
    }

    drawSprite(x, y, height) {
        let sprite = this.memory[this.i];
        for (let j = 0; j < height; j++) {
            if (j >= 16) break;
            const srcY = sprite & 0x0F;
            const dstX = x + ((srcY >> 3) & 0x07);
            const dstY = y + ((srcY >> 4) & 0x01);

            for (let k = 0; k < 8; k++) {
                if (j >= 16) break;
                const bit = this.memory[this.i + j] & (1 << (7 - k)) ? 1 : 0;

                if (bit && dstY >= 0 && dstY < 32) {
                    let collision = false;
                    for (let col = 0; col < 8; col++) {
                        const srcByte = this.memory[this.i + j] >> col & 1;
                        if (srcByte) {
                            const pixelX = x + ((srcByte >> col) & 1);
                            const pixelY = y + ((srcByte >> col) & 1);

                            if (pixelY >= 0 && pixelY < 32) {
                                this.memory[y * 64 + x] ^= 1;
                                collision = true;
                            }
                        }
                    }
                }
            }
        }
    }

    push() {
        if (this.sp < 64) {
            this.stack[this.sp] = this.pc - 2;
            this.sp++;
        }
    }

    run() {
        if (!this.running) {
            this.running = true;
            this.frameInterval();
        }
    }

    pause() {
        this.running = false;
    }

    singleStep() {
        const instruction = this.interpret();
        document.getElementById('currentInstruction').textContent = `PC: 0x${this.toHex(this.pc)} | ${instruction}`;
        this.draw();
        this.updateDebugger();

        if (this.delayLoop) {
            return;
        }
    }

    reset() {
        this.running = false;
        this.pc = 0x200;
        this.i = 0;
        this.sp = 0;
        this.delayTimer = 0;
        this.soundTimer = 0;
        this.keysPressed.clear();
        this.keyboardState.fill(0);
        this.clearFlags();

        // Clear memory and registers
        this.memory.fill(0);
        this.v.fill(0);
        this.stack.fill(0);

        // Reload font set
        const fontSet = [
            0xF0, 0x90, 0x90, 0x90, 0xF0, 0x20, 0x60, 0x20, 0x20, 0x70,
            0xF0, 0x10, 0xF0, 0x80, 0xF0, 0xF0, 0x10, 0xF0, 0x80, 0xF0,
            0xF0, 0x90, 0xF0, 0x10, 0xF0, 0xF0, 0x90, 0xF0, 0x90, 0xF0,
            0xF0, 0x80, 0xF0, 0x80, 0xF0, 0xF0, 0x80, 0xF0, 0x80, 0xF0,
            0xF0, 0x80, 0xF0, 0x80, 0xF0, 0xF0, 0x10, 0x10, 0x40, 0xF0,
            0x90, 0x90, 0x90, 0x70, 0xF0, 0xF0, 0x80, 0x80, 0x80, 0xF0,
            0xF0, 0x10, 0x20, 0x40, 0x40, 0xF0, 0x90, 0x90, 0x90, 0x70, 0xF0,
            0xF0, 0x90, 0xF0, 0x10, 0xF0, 0xF0, 0x80, 0xF0, 0x80, 0xF0,
        ];
        for (let i = 0; i < fontSet.length; i++) {
            this.memory[0x050 + i] = fontSet[i];
        }

        this.updateDebugger();
    }

    loadRom(file) {
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target.result;
                // Try to parse as hex or binary data
                let romData = [];

                if (content.trim().startsWith('[')) {
                    // Array format
                    const matches = content.match(/\[([\s\S]*?)\]/);
                    if (matches) {
                        romData = matches[1].split(',').map(s => parseInt(s.trim(), 16));
                    }
                } else if (content.trim().startsWith('{')) {
                    // JSON format with hex values
                    try {
                        const obj = JSON.parse(content);
                        if (Array.isArray(obj)) {
                            romData = obj.map(s => parseInt(s, 16));
                        } else if (obj.hex) {
                            romData = obj.hex.split(',').map(s => parseInt(s.trim(), 16));
                        }
                    } catch (e) {}
                } else {
                    // Raw hex string
                    romData = content.trim().split(/[\s,]+/).filter(s => s.length === 2).map(s => parseInt(s, 16));
                }

                // Load ROM into memory starting at 0x200
                for (let i = 0; i < romData.length && this.pc + i < 4096; i++) {
                    this.memory[this.pc + i] = romData[i];
                }

                console.log(`Loaded ROM: ${romData.length} bytes`);
                alert('ROM loaded successfully! Press Run to start.');
            } catch (error) {
                console.error('Error loading ROM:', error);
                alert('Error loading ROM file. Please check the format.');
            }
        };
        reader.readAsText(file);
    }

    frameInterval() {
        if (!this.running) return;

        this.updateSpeed(this.speed);

        while (this.instructionsExecutedThisFrame < this.speed && !this.delayLoop) {
            const instruction = this.interpret();
            this.pc += 2;

            // Handle timer updates
            if (this.delayTimer > 0) {
                this.delayTimer--;
            }
            if (this.soundTimer > 0) {
                this.soundTimer--;
            }

            // Check for key presses after each instruction
            for (const code of [...this.keysPressed]) {
                const keyEl = document.querySelector(`.key[data-code="${code}"]`);
                if (keyEl) keyEl.classList.add('pressed');
            }
        }

        this.draw();
        this.updateDebugger();

        setTimeout(() => {
            requestAnimationFrame(this.frameInterval.bind(this));
        }, 16);
    }

    updateSpeed(speed) {
        this.speed = parseInt(speed);
        document.getElementById('speedValue').textContent = speed;
    }

    updateDebugger() {
        // Update registers display
        const regText = 'V0: 0x' + this.toHex(this.v[0]).padStart(2, '0') + 
                        ', V1: 0x' + this.toHex(this.v[1]).padStart(2, '0') +
                        ', V2: 0x' + this.toHex(this.v[2]).padStart(2, '0') +
                        ', V3: 0x' + this.toHex(this.v[3]).padStart(2, '0') +
                        ', V4: 0x' + this.toHex(this.v[4]).padStart(2, '0') +
                        ', V5: 0x' + this.toHex(this.v[5]).padStart(2, '0') +
                        ', V6: 0x' + this.toHex(this.v[6]).padStart(2, '0') +
                        ', V7: 0x' + this.toHex(this.v[7]).padStart(2, '0') +
                        ', V8: 0x' + this.toHex(this.v[8]).padStart(2, '0') +
                        ', V9: 0x' + this.toHex(this.v[9]).padStart(2, '0') +
                        ', VA: 0x' + this.toHex(this.v[10]).padStart(2, '0') +
                        ', VB: 0x' + this.toHex(this.v[11]).padStart(2, '0') +
                        ', VC: 0x' + this.toHex(this.v[12]).padStart(2, '0') +
                        ', VD: 0x' + this.toHex(this.v[13]).padStart(2, '0') +
                        ', VE: 0x' + this.toHex(this.v[14]).padStart(2, '0') +
                        ', VF: 0x' + this.toHex(this.v[15]).padStart(2, '0');
        document.getElementById('registers').textContent = regText;

        // Update IP/PC/SP display
        const ipRegPcSp = `I: 0x${this.toHex(this.i).padStart(4, '0')} | PC: 0x${this.toHex(this.pc).padStart(4, '0')} | SP: 0x${this.toHex(this.sp).padStart(2, '0')}`;
        document.getElementById('ip-register-pc-sp').textContent = ipRegPcSp;

        // Update timers display
        const timers = `Delay Timer: ${this.delayTimer} | Sound Timer: ${this.soundTimer}`;
        document.getElementById('timers').textContent = timers;

        // Update stack display (show last 8 entries)
        let stackText = 'Stack:';
        for (let i = this.sp - 1; i >= Math.max(0, this.sp - 8); i--) {
            if (i >= 0) {
                stackText += ` [${this.toHex(this.stack[i]).padStart(2, '0')}]`;
            }
        }
        document.getElementById('stack').textContent = stackText;
    }

    toHex(num) {
        return num.toString(16);
    }
}

